import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"Tensor","link":"/api/SIMD-API/tensor_api/tensor/tensor_structure"},{"text":"make_mem_ptr","link":"/api/SIMD-API/tensor_api/tensor/make_mem_ptr"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/tensor/make_mem_ptr.md","filePath":"api/SIMD-API/tensor_api/tensor/make_mem_ptr.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787967772000}'),t={name:"api/SIMD-API/tensor_api/tensor/make_mem_ptr.md"};function c(e,s,i,r,o,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>make_mem_ptr</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>。</p><p>make_mem_ptr用于构造带物理存储位置标记和数据类型信息的内存指针适配器<code>hardware_mem_ptr</code>，支持的物理位置如下表所示。</p><p>make_mem_ptr提供三种调用形式：</p><ol><li>指定物理位置和数据类型，根据原始地址构造指针。</li><li>指定物理位置，从已有迭代器或指针适配器构造新指针。</li><li>从已有迭代器或指针适配器中自动推导物理位置。</li></ol><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>指定物理位置和数据类型，根据原始地址构造：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">PtrPattern</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DataType</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Addr</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">Addr</span><span class="w"> </span><span class="n">address</span><span class="p">)</span>
</code></pre></div></li><li><p>指定物理位置，从已有迭代器构造：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">PtrPattern</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Iterator</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">Iterator</span><span class="w"> </span><span class="n">iterator</span><span class="p">)</span>
</code></pre></div></li><li><p>从已有迭代器中自动推导物理位置：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Iterator</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">Iterator</span><span class="w"> </span><span class="n">iterator</span><span class="p">)</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 支持的物理位置</p><table><thead><tr><th align="left">location</th><th align="left">说明</th><th align="left">用途</th></tr></thead><tbody><tr><td align="left">location::gm</td><td align="left">Global Memory</td><td align="left">全局内存，张量输入输出的主要存储区域</td></tr><tr><td align="left">location::l1</td><td align="left">L1 Buffer</td><td align="left">一级缓存，矩阵搬运和计算前的数据暂存区</td></tr><tr><td align="left">location::l0a</td><td align="left">L0A Buffer</td><td align="left">矩阵计算左输入缓存</td></tr><tr><td align="left">location::l0b</td><td align="left">L0B Buffer</td><td align="left">矩阵计算右输入缓存</td></tr><tr><td align="left">location::l0scalea</td><td align="left">L0 ScaleA Buffer</td><td align="left">MX矩阵计算ScaleA缓存</td></tr><tr><td align="left">location::l0scaleb</td><td align="left">L0 ScaleB Buffer</td><td align="left">MX矩阵计算ScaleB缓存</td></tr><tr><td align="left">location::l0c</td><td align="left">L0C Buffer</td><td align="left">矩阵计算结果缓存</td></tr><tr><td align="left">location::ub</td><td align="left">UB</td><td align="left">统一缓存，矢量计算的数据存储区</td></tr><tr><td align="left">location::bias</td><td align="left">BiasTable Buffer</td><td align="left">偏置表缓存，带偏置矩阵计算的偏置存放区</td></tr><tr><td align="left">location::fixbuf</td><td align="left">Fixpipe Buffer</td><td align="left">Fixpipe输出缓存，L0C到GM/UB的中转区</td></tr></tbody></table><p><strong>表2</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">类型</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">PtrPattern</td><td align="center">输入</td><td align="left">物理存储位置类型。</td></tr><tr><td align="left">DataType</td><td align="center">输入</td><td align="left">数据类型。</td></tr><tr><td align="left">Addr</td><td align="center">输入</td><td align="left">偏移量数值的类型。</td></tr><tr><td align="left">Iterator</td><td align="center">输入</td><td align="left">迭代器类型或已有指针适配器类型。</td></tr></tbody></table><p><strong>表3</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">类型</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">address</td><td align="center">输入</td><td align="left">地址偏移量，即相对于基地址的偏移大小。</td></tr><tr><td align="left">iterator</td><td align="center">输入</td><td align="left">已有的硬件地址迭代器或指针适配器对象。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回<code>hardware_mem_ptr&lt;PtrPattern, Pointer&gt;</code>类型的指针适配器对象，其中：</p><ul><li>PtrPattern表示指定或推导得到的物理位置；</li><li>Pointer表示对应地址空间下的指针类型，例如__gm__ float*、__cbuf__ half*等。</li></ul><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>指定PtrPattern时，必须是受支持的物理位置类型。</li><li>Iterator需要满足对应构造路径的模板约束。</li><li>自动推导形式要求输入对象本身已经带有可识别的硬件位置信息。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">gm_offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">l1_offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">l0a_offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">ub_offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="c1">// 1. 从原始地址构造：指定物理位置和数据类型</span>
<span class="k">auto</span><span class="w"> </span><span class="n">gm_ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">gm</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">gm_offset</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l1_ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">l1</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">l1_offset</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l0a_ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">l0a</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="n">l0a_offset</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">ub_ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">ub</span><span class="p">,</span><span class="w"> </span><span class="n">bfloat16_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">ub_offset</span><span class="p">);</span>

<span class="c1">// 2. 配合make_tensor构造张量</span>
<span class="k">auto</span><span class="w"> </span><span class="n">gm_a</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">gm_ptr</span><span class="p">,</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">layout_trait_default</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l1_a</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">l1_ptr</span><span class="p">,</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">layout_trait_default</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>

<span class="c1">// 3. 从已有指针适配器继承位置（自动推导）</span>
<span class="k">auto</span><span class="w"> </span><span class="n">another_ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">gm_ptr</span><span class="p">);</span>

<span class="c1">// 4. 从已有迭代器指定新位置</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l1_from_iter</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">l1</span><span class="o">&gt;</span><span class="p">(</span><span class="n">some_iterator</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const f=a(t,[["render",c]]);export{_ as __pageData,f as default};
